<script setup lang="ts">import{ref}from'vue';import{memories,chapters}from'../data/chapters';import{useAppStore}from'../stores/app';import{LockKeyhole,Heart,BookOpen,Star}from'@lucide/vue';const tab=ref<'memories'|'study'>('memories'),store=useAppStore()</script>
<template><section class="page"><header class="page-head"><p class="eyebrow">OUR JOURNEY</p><h1>{{store.activeCharacter.name}}との思い出</h1></header><div class="tabs"><button :class="{active:tab==='memories'}" @click="tab='memories'">Memories</button><button :class="{active:tab==='study'}" @click="tab='study'">Study</button></div><div v-if="tab==='memories'" class="memory-grid"><article v-for="m in memories" :class="{locked:!store.progress.completed.includes(m.chapterId)}"><template v-if="store.progress.completed.includes(m.chapterId)"><div class="memory-photo"><img :src="chapters[m.chapterId-1].image" :alt="m.title"/><Heart fill="currentColor"/></div><small>MEMORY 0{{m.chapterId}}</small><h3>{{m.title}}</h3><p>{{m.description}}</p><q>{{m.expression}}</q></template><template v-else><LockKeyhole/><b>？？？</b><small>Chapter {{m.chapterId}}で解放</small></template></article></div><div v-else><div class="study-hero"><Star/><small>ENGLISH XP</small><strong>{{store.s.xp}}</strong><p>{{store.s.studyDays}}日間の学びを積み重ねました</p></div><div class="study-stats"><div><b>{{store.learnedCount}}</b><span>学んだ表現</span></div><div><b>{{store.progress.reviews.length}}</b><span>復習中</span></div><div><b>{{store.progress.completed.length}}</b><span>クリア章</span></div></div><div class="card"><h3><BookOpen/> 学習済みチャプター</h3><p v-for="c in chapters"><span>{{c.icon}} {{c.title}}</span><b>{{store.progress.completed.includes(c.id)?'COMPLETED':'—'}}</b></p></div></div></section></template>
